+    const folder = mkdtempSync(join(tmpdir(), "hosted-stream-"));
+    const path = join(folder, "agent.jsonl");
+    writeFileSync(path, "");
+    let now = 0;
+    const clock = spyOn(Date, "now").mockImplementation(() => { now += 120_000; return now; });
+    let progress = 0;
+    let answer: HostedAnswer | undefined;
+    /** @yields {StepEvent} Chunks whose signed rows arrive only at the response's stop. */
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "Think" } };
+      yield { kind: "item", item: { kind: "text", index: 2, text: "Hello" } };
+      yield { kind: "item", item: { kind: "text", index: 2, text: " world" } };
+      appendFileSync(path, JSON.stringify({ type: "assistant", message: { content: [
+        { type: "thinking", thinking: "Thinking", signature: "signed" },
+        { type: "redacted_thinking", data: "redacted" },
+      ] } }) + "\n");
+      yield stop;
+    }
