+++ b/tests/unit/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.test.ts
@@ -0,0 +1,92 @@
+import { expect, spyOn, test } from "bun:test";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+const item = (item: HostStepItem): StepEvent => ({ kind: "item", item });
+const thinking = item({ kind: "thinking", index: 0, text: "Plan" });
+const text = (text: string) => item({ kind: "text", index: 2, text });
+const stop = item({ kind: "stop", stopReason: "end_turn", usage: null });
+const signed: SignedBlock = { type: "thinking", thinking: "Plan.", signature: "engine-signature" };
+const redacted: SignedBlock = { type: "redacted_thinking", data: "engine-data" };
+const serviceError = new Error("404 status code (no body)");
+const failure = async () => serviceError;
+
+test("an ended step without a stop reports the service failure even when a signed row is pending", async () => {
+  async function* events() {
+    yield thinking;
+    yield text("partial");
+    yield { kind: "done" } satisfies StepEvent;
+  }
+  const stream = hostedStreamEvents(events(), { read: () => [] }, 0, "model", failure, () => {}, () => {});
+  await expect(Array.fromAsync(stream)).rejects.toBe(serviceError);
+}, 12_000);
+
+test("later chunks report progress but stay behind signed blocks until the engine writes their rows", async () => {
+  let progress = 0;
+  let stopped = false;
+  let rowsReady = false;
+  const answers: HostedAnswer[] = [];
+  async function* events() {
+    yield thinking;
+    yield text("first");
+    expect(progress).toBe(2);
+    yield text(" last");
+    expect(progress).toBe(3);
+    stopped = true;
+    yield stop;
+  }
+  const rows = {
+    read: () => {
+      if (!stopped) return [];
+      if (rowsReady) return [signed, redacted];
+      rowsReady = true;
+      return [];
+    },
+  };
+  const stream = hostedStreamEvents(events(), rows, 0, "model", failure, (answer) => answers.push(answer), () => { progress += 1; });
+  const [start, ...eventsAfterStart] = await Array.fromAsync(stream);
+  expect(start?.type).toBe("message_start");
+  expect(eventsAfterStart).toMatchObject([
+    { type: "content_block_start", index: 0, content_block: { type: "thinking" } },
+    { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "Plan" } },
+    { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "." } },
+    { type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "engine-signature" } },
+    { type: "content_block_stop", index: 0 },
+    { type: "content_block_start", index: 1, content_block: { type: "redacted_thinking", data: "engine-data" } },
+    { type: "content_block_stop", index: 1 },
+    { type: "content_block_start", index: 2, content_block: { type: "text" } },
+    { type: "content_block_delta", index: 2, delta: { type: "text_delta", text: "first" } },
+    { type: "content_block_delta", index: 2, delta: { type: "text_delta", text: " last" } },
+    { type: "content_block_stop", index: 2 },
+    { type: "message_delta", delta: { stop_reason: "end_turn" } },
+    { type: "message_stop" },
+  ]);
+  expect(answers).toEqual([{ message: { role: "assistant", content: [signed, redacted, { type: "text", text: "first last" }] }, stopReason: "end_turn" }]);
+  expect(progress).toBe(4);
+});
+
+test("a row missing after the stop fails transiently without reporting polls as progress", async () => {
+  let now = Date.now();
+  const clock = spyOn(Date, "now").mockImplementation(() => now);
+  try {
+    let stopped = false;
+    let progress = 0;
+    async function* events() {
+      yield thinking;
+      yield text("partial");
+      now += 120_000;
+      stopped = true;
+      yield stop;
+    }
+    const rows = { read: () => { if (stopped) now += 1_000; return []; } };
+    const stream = hostedStreamEvents(events(), rows, 0, "model", failure, () => {}, () => { progress += 1; });
+    await expect(Array.fromAsync(stream)).rejects.toMatchObject({
+      name: LlmStreamError.name, kind: "transient", message: expect.stringContaining("wrote no row"),
+    });
+    expect(progress).toBe(3);
+  } finally {
+    clock.mockRestore();
+  }
+});

