@@ -0,0 +1,18 @@
+import type { Rollup } from "./types.js";
+
+/** Stores rollups by metric for the collector and pull-based readers. */
+export class MetricsStore {
+  private readonly byMetric = new Map<string, Rollup[]>();
+
+  /** Appends a rollup without replacing earlier windows for the same metric. */
+  append(rollup: Rollup): void {
+    const rollups = this.byMetric.get(rollup.metric);
+    if (rollups) rollups.push(rollup);
+    else this.byMetric.set(rollup.metric, [rollup]);
+  }
+
+  /** Returns stored rollups in insertion order, or an empty collection for an unknown metric. */
+  read(metric: string): readonly Rollup[] {
+    return this.byMetric.get(metric) ?? [];
+  }
+}
