+import type { NestedTestConfig } from '../types';
+
+export default function getNestedOptions({
+  key,
+  index,
+  parent,
+  parentPath,
+  originalParent,
+  options,
+}: NestedTestConfig) {
+  const k = key ?? index;
+  if (k == null) {
+    throw TypeError('Must include `key` or `index` for nested validations');
+  }
+
+  const isIndex = typeof k === 'number';
+
+  return {
+    ...options,
+    parent,
+    originalValue: originalParent[k],
+    // Keep the array index available to fields nested within the item.
+    key: undefined,
+    [isIndex ? 'index' : 'key']: k,
+    path:
+      isIndex || k.includes('.')
+        ? `${parentPath || ''}[${isIndex ? k : `"${k}"`}]`
+        : (parentPath ? `${parentPath}.` : '') + key,
+  };
+}
