--- /dev/null
+++ b/src/util/getNestedOptions.ts
@@ -0,0 +1,56 @@
+import type { InternalOptions, NestedTestConfig } from '../types';
+
+export function getNestedOptions<TContext>(
+  options: InternalOptions<TContext>,
+  {
+    parent,
+    parentPath,
+    key,
+    value,
+    originalValue,
+  }: {
+    parent: any;
+    parentPath?: string;
+    key: string | number;
+    value: any;
+    originalValue: any;
+  },
+) {
+  const isIndex = typeof key === 'number';
+
+  return {
+    ...options,
+    parent,
+    value,
+    originalValue,
+    // Keep inherited indexes for object fields, but not inherited keys.
+    key: undefined,
+    [isIndex ? 'index' : 'key']: key,
+    path:
+      isIndex || key.includes('.')
+        ? `${parentPath || ''}[${isIndex ? key : `"${key}"`}]`
+        : (parentPath ? `${parentPath}.` : '') + key,
+  };
+}
+
+export function getNestedTestOptions({
+  key,
+  index,
+  parent,
+  parentPath,
+  originalParent,
+  options,
+}: NestedTestConfig) {
+  const k = key ?? index;
+  if (k == null) {
+    throw TypeError('Must include `key` or `index` for nested validations');
+  }
+
+  return getNestedOptions(options, {
+    parent,
+    parentPath,
+    key: k,
+    value: parent[k],
+    originalValue: originalParent[k],
+  });
+}
