--- /dev/null
+++ b/parser.ts
@@ -0,0 +1,37 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | Extract<TemplateToken, { kind: "text" | "variable" }>
+  | (Extract<TemplateToken, { kind: "open" }> & { children: TemplateNode[] });
+
+/** Builds a nested tree, throwing TemplateError at an invalid close or unclosed open. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const nodes: TemplateNode[] = [];
+  const stack: Extract<TemplateNode, { kind: "open" }>[] = [];
+  let children = nodes;
+  for (const token of tokens) {
+    if (token.kind === "open") {
+      const node = { ...token, children: [] };
+      children.push(node);
+      stack.push(node);
+      children = node.children;
+    } else if (token.kind === "close") {
+      const open = stack.at(-1);
+      if (!open) {
+        throw new TemplateError(`Unexpected closing ${token.block} tag`, token.position);
+      }
+      if (open.block !== token.block) {
+        throw new TemplateError(`Mismatched closing ${token.block} tag`, token.position);
+      }
+      stack.pop();
+      children = stack.at(-1)?.children ?? nodes;
+    } else {
+      children.push(token);
+    }
+  }
+  const unclosed = stack.at(-1);
+  if (unclosed) {
+    throw new TemplateError(`Unclosed ${unclosed.block} block`, unclosed.position);
+  }
+  return nodes;
+}
