+function resolve(path: string, context: unknown): unknown {
+  let value = context;
+  for (const segment of path.split(".")) {
+    value = (value as Record<string, unknown> | null | undefined)?.[segment];
+  }
+  return value;
+}
+
+function renderNodes(nodes: readonly TemplateNode[], context: unknown): string {
+  return nodes.map((node): string => {
+    if (node.kind === "text") return node.value;
+    const value = resolve(node.path, context);
+    if (node.kind === "variable") {
+      const text = value == null ? "" : String(value);
+      return node.escaped
+        ? text.replaceAll("&", "&amp;")
+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;")
+          .replaceAll('"', "&quot;")
+          .replaceAll("'", "&#39;")
+        : text;
+    }
+    if (node.block === "if") {
+      return value ? renderNodes(node.children, context) : "";
+    }
+    return Array.isArray(value)
+      ? value.map((item) => renderNodes(node.children, item)).join("")
+      : "";
+  }).join("");
+}
+
+/**
+ * Renders escaped or raw dot-path variables and nested if/each blocks.
+ * Each body uses its item as context. Nullish values render as empty text.
+ * Throws TemplateError for invalid block structure, including in omitted bodies.
+ */
+export function render(template: string, context: TemplateContext = {}): string {
+  return renderNodes(parse(tokenize(template)), context);
 }
