+const thinking: StepEvent = { kind: "item", item: { kind: "thinking", index: 0, text: "Think" } };
+const text: StepEvent = { kind: "item", item: { kind: "text", index: 1, text: "Answer" } };
+const signed: SignedBlock = { type: "thinking", thinking: "Thinking", signature: "engine-signature" };
+const serviceFailure = new Error("service failed before stop");
