+async function collect(events: AsyncIterable<Anthropic.RawMessageStreamEvent>) {
+  return Array.fromAsync(events);
+}
+
+/** The engine's file boundary, including incomplete rows and earlier signed blocks. */
+function file() {
+  const directory = mkdtempSync(join(tmpdir(), "hosted-stream-"));
+  const path = join(directory, "agent.jsonl");
+  writeFileSync(path, "");
+  return {
+    rows: agentRows(path, 0),
+    append: (content: readonly SignedBlock[]) => appendFileSync(path, `${JSON.stringify({ type: "assistant", message: { content } })}\n`),
+    remove: () => rmSync(directory, { recursive: true, force: true }),
+  };
+}
+
+describe("the hosted response stream", () => {
+  for (const redacted of [false, true]) {
+    test(`consumes a long response before its signed row arrives and preserves block order (${redacted ? "redacted" : "thinking"})`, async () => {
