+      const now = spyOn(Date, "now").mockImplementation(() => { clock += 60_001; return clock; });
+      let progress = 0;
+      let answer: HostedAnswer | undefined;
+      const earlier: SignedBlock = { type: "thinking", thinking: "Earlier", signature: "earlier-signature" };
+      engine.append([earlier]);
+      async function* events(): AsyncGenerator<StepEvent> {
+        if (!redacted) yield thinking;
+        yield text;
+        for (let index = 0; index < 4; index += 1) {
+          clock += 30_000;
+          yield { kind: "item", item: { kind: "text", index: 1, text: "." } };
+        }
+        engine.append([redacted ? { type: "redacted_thinking", data: "engine-data" } : signed]);
+        yield stop;
+      }
+      try {
+        const output = await collect(hostedStreamEvents(events(), engine.rows, 1, "model", async () => serviceFailure, (value) => { answer = value; }, () => { progress += 1; }));
+        expect(progress).toBe(redacted ? 6 : 7);
+        expect(answer?.message.content).toEqual([redacted ? { type: "redacted_thinking", data: "engine-data" } : signed, { type: "text", text: "Answer...." }]);
+        const blocks = output.filter((event) => event.type !== "message_start");
+        if (redacted) {
+          expect(blocks.slice(0, 2)).toEqual([
