+            { type: "content_block_start", index: 0, content_block: { type: "thinking", thinking: "", signature: "" } },
+            { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "Think" } },
+            { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "ing" } },
+            { type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "engine-signature" } },
+            { type: "content_block_stop", index: 0 },
+          ]);
+        }
+        expect(blocks[redacted ? 2 : 5]).toMatchObject({ type: "content_block_start", index: 1 });
+        expect(output.at(-1)).toEqual({ type: "message_stop" });
+      } finally {
+        now.mockRestore();
+        engine.remove();
+      }
+    });
+  }
+
+  test("fails transient when the stop chunk arrives without a signed row", async () => {
