+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      yield text;
+      stopped = true;
+      yield stop;
+    }
+    try {
+      const failure = await collect(hostedStreamEvents(events(), { read: () => [] }, 0, "model", async () => serviceFailure, () => {}, () => {})).catch((error: unknown) => error);
+      expect(failure).toBeInstanceOf(LlmStreamError);
+      expect(failure).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+      expect(stopped).toBe(true);
+    } finally {
+      now.mockRestore();
+    }
+  });
+
+  test("uses the service failure when the step ends without stop while waiting for a row", async () => {
+    const now = spyOn(Date, "now").mockImplementationOnce(() => 0).mockImplementation(() => 60_001);
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      yield text;
+      yield { kind: "done" };
+    }
+    try {
+      await expect(collect(hostedStreamEvents(events(), { read: () => [] }, 0, "model", async () => serviceFailure, () => {}, () => {}))).rejects.toBe(serviceFailure);
+    } finally {
+      now.mockRestore();
+    }
+  });
+
+  for (const stalls of [false, true]) {
+    test(`the real reasoning deadline ${stalls ? "ends a silent source" : "allows ongoing chunks while the row is pending"}`, async () => {
+      const previous = process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+      process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "100";
+      const engine = file();
+      let progress = 0;
+      let closed = false;
+      const output = withStreamAttempt(async function* (attempt) {
+        const liveness = armStreamLiveness(attempt, { label: "hosted-stream-test", provider: "test", telemetry: undefined });
+        async function* events(): AsyncGenerator<StepEvent> {
+          try {
+            yield thinking;
+            yield text;
+            if (stalls) await abortableSleep(10_000, attempt.signal);
+            for (let index = 0; index < 12; index += 1) {
+              await abortableSleep(20, attempt.signal);
+              yield { kind: "item", item: { kind: "text", index: 1, text: "." } };
+            }
+            engine.append([signed]);
+            yield stop;
+          } finally {
+            closed = true;
+          }
+        }
+        for await (const event of hostedStreamEvents(events(), engine.rows, 0, "model", async () => serviceFailure, () => {}, () => { progress += 1; liveness.frame(); })) {
+          liveness.frame();
