+        }
+      }, {});
+      try {
+        if (stalls) {
+          await expect(Array.fromAsync(output)).rejects.toMatchObject({ cause: expect.any(ThinkingStallError) });
+          expect(progress).toBe(2);
+        } else {
+          expect((await Array.fromAsync(output)).at(-1)).toEqual({ type: "message_stop" });
+          expect(progress).toBe(15);
+        }
+        expect(closed).toBe(true);
+      } finally {
+        if (previous === undefined) delete process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+        else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = previous;
+        engine.remove();
+      }
+    });
+  }
