+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | Extract<TemplateToken, { kind: "text" | "variable" }>
+  | { kind: "if" | "each"; path: string; children: TemplateNode[] };
+
+/** Builds a template tree from tokens or throws TemplateError for an unmatched block tag. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: { token: Extract<TemplateToken, { kind: "open" }>; children: TemplateNode[] }[] = [];
+
+  for (const token of tokens) {
+    const open = stack.at(-1);
+    if (token.kind === "close") {
+      if (!open) {
+        throw new TemplateError(`Unexpected closing tag /${token.block}`, token.position);
+      }
+      if (open.token.block !== token.block) {
+        throw new TemplateError(
+          `Mismatched closing tag: expected /${open.token.block}, got /${token.block}`,
+          token.position,
+        );
+      }
+      stack.pop();
+      continue;
+    }
+
+    const siblings = open?.children ?? root;
+    if (token.kind === "open") {
+      const children: TemplateNode[] = [];
+      siblings.push({ kind: token.block, path: token.path, children });
+      stack.push({ token, children });
+    } else {
+      siblings.push(token);
+    }
+  }
+
+  const unclosed = stack.at(-1);
+  if (unclosed) {
+    throw new TemplateError(`Unclosed block #${unclosed.token.block}`, unclosed.token.position);
+  }
+  return root;
+}
