+    if (step.done) {
+      stack.pop();
+      continue;
+    }
+
+    const { node, context: scope } = step.value;
+    if (node.kind === "text") {
+      output.push(node.value);
+      continue;
+    }
+
+    const value = resolvePath(node.path, scope);
+    if (node.kind === "variable") {
+      const text = value == null ? "" : String(value);
+      output.push(node.escaped ? escapeHtml(text) : text);
+    } else if (node.kind === "if") {
+      if (value) stack.push(scopedNodes(node.children, [scope]));
+    } else if (Array.isArray(value)) {
+      stack.push(scopedNodes(node.children, value));
+    }
+  }
+  return output.join("");
+}
+
+function* scopedNodes(nodes: readonly TemplateNode[], contexts: Iterable<unknown>) {
+  for (const context of contexts) {
+    for (const node of nodes) {
+      yield { node, context };
+    }
+  }
+}
+
+function resolvePath(path: string, context: unknown): unknown {
+  let value = context;
+  for (const segment of path.split(".")) {
+    if (value == null) return undefined;
+    value = (value as Readonly<Record<string, unknown>>)[segment];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
 }
