@@ -0,0 +1,18 @@
+import type { Rollup } from "./types.js";
+
+/** Stores rollups by metric for pull-based readers. */
+export class MetricsStore {
+  private readonly rollups = new Map<string, Rollup[]>();
+
+  /** Appends a completed rollup to its metric's history. */
+  append(rollup: Rollup): void {
+    const history = this.rollups.get(rollup.metric);
+    if (history) history.push(rollup);
+    else this.rollups.set(rollup.metric, [rollup]);
+  }
+
+  /** Returns a metric's rollups in insertion order, or an empty collection. */
+  read(metric: string): readonly Rollup[] {
+    return this.rollups.get(metric) ?? [];
+  }
+}
