+import { expect, spyOn, test } from "bun:test";
+import { appendFileSync, mkdtempSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { agentRows } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+const failure = new Error("404 status code (no body)");
+const chunk = (item: HostStepItem): StepEvent => ({ kind: "item", item });
+const thinking = chunk({ kind: "thinking", index: 0, text: "Reason" });
+const text = chunk({ kind: "text", index: 2, text: "Answer" });
+const stop = chunk({ kind: "stop", stopReason: "end_turn", usage: null });
+const done: StepEvent = { kind: "done" };
+const noAnswer = () => { throw new Error("An incomplete response cannot record an answer"); };
+
+test("late transcript rows complete thinking before later blocks, without treating live chunks as a stall", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "hosted-stream-"));
+  const path = join(dir, "agent.jsonl");
+  const signed = { type: "thinking", thinking: "Reasoning", signature: "signature" };
+  const redacted = { type: "redacted_thinking", data: "redacted data" };
+  let now = 0;
+  let stopped = false;
+  let progress = 0;
+  let answer: HostedAnswer | undefined;
+  let persist: ReturnType<typeof setTimeout> | undefined;
+  const clock = spyOn(Date, "now").mockImplementation(() => stopped ? now : (now += 61_000));
+  async function* events(): AsyncGenerator<StepEvent> {
+    yield thinking;
+    yield text;
+    const before = progress;
+    yield chunk({ kind: "text", index: 2, text: " continues" });
+    expect(progress).toBeGreaterThan(before);
+    stopped = true;
+    // The hook can forward the stop chunk before the engine persists the signed blocks.
+    persist = setTimeout(() => {
+      appendFileSync(path, `${JSON.stringify({ type: "assistant", message: { content: [signed, redacted] } })}\n`);
+    }, 0);
+    yield stop;
+  }
+  try {
+    const stream = hostedStreamEvents(events(), agentRows(path, 0), 0, "model", async () => failure, (value) => { answer = value; }, () => { progress++; });
+    const output = await Array.fromAsync(stream);
+    expect(output.map((event) => event.type === "content_block_delta" ? event.delta.type : event.type)).toEqual([
+      "message_start", "content_block_start", "thinking_delta", "thinking_delta", "signature_delta", "content_block_stop",
+      "content_block_start", "content_block_stop", "content_block_start", "text_delta", "text_delta", "content_block_stop",
+      "message_delta", "message_stop",
+    ]);
+    expect(output[4]).toEqual({ type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "signature" } });
+    expect(output[6]).toEqual({ type: "content_block_start", index: 1, content_block: redacted });
+    expect(answer?.message.content).toEqual([signed, redacted, { type: "text", text: "Answer continues" }]);
+  } finally {
+    clearTimeout(persist);
+    clock.mockRestore();
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+test.each([
+  { terminal: done, ending: "without a stop chunk", error: failure },
+  { terminal: stop, ending: "with a stop chunk", error: { kind: "transient", message: expect.stringContaining("wrote no row") } },
+])("missing rows preserve the failure when the step ends $ending", async ({ terminal, error }) => {
+  let now = 0;
+  const clock = spyOn(Date, "now").mockImplementation(() => (now += 61_000));
+  async function* events(): AsyncGenerator<StepEvent> {
+    yield thinking;
+    yield text;
+    yield terminal;
