@@ -0,0 +1,47 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+type BlockNode = Omit<Extract<TemplateToken, { kind: "open" }>, "kind"> & {
+  kind: "block";
+  children: TemplateNode[];
+};
+
+export type TemplateNode = Extract<TemplateToken, { kind: "text" | "variable" }> | BlockNode;
+
+/** Builds a nested tree or throws TemplateError at the offending delimiter. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: BlockNode[] = [];
+
+  for (const token of tokens) {
+    const open = stack[stack.length - 1];
+    const children = open?.children ?? root;
+    switch (token.kind) {
+      case "open": {
+        const block: BlockNode = { ...token, kind: "block", children: [] };
+        children.push(block);
+        stack.push(block);
+        break;
+      }
+      case "close":
+        if (!open) {
+          throw new TemplateError(`Unexpected closing tag: /${token.block}`, token.position);
+        }
+        if (open.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing tag: expected /${open.block}, got /${token.block}`,
+            token.position,
+          );
+        }
+        stack.pop();
+        break;
+      default:
+        children.push(token);
+    }
+  }
+
+  const unclosed = stack[stack.length - 1];
+  if (unclosed) {
+    throw new TemplateError(`Unclosed block: #${unclosed.block}`, unclosed.position);
+  }
+  return root;
+}
