+/** Renders a template against its context. Invalid block structure throws TemplateError. */
+export function render(template: string, context: TemplateContext = {}): string {
+  const stack = [nodesInScopes(parse(tokenize(template)), [context])];
+  const output: string[] = [];
+
+  while (stack.length > 0) {
+    const next = stack[stack.length - 1].next();
+    if (next.done) {
+      stack.pop();
+      continue;
+    }
+    const { node, scope } = next.value;
+    switch (node.kind) {
+      case "text":
+        output.push(node.value);
+        break;
+      case "variable": {
+        const value = resolvePath(scope, node.path);
+        const text = value == null ? "" : String(value);
+        output.push(node.escaped ? escapeHtml(text) : text);
+        break;
+      }
+      case "block": {
+        const value = resolvePath(scope, node.path);
+        if (node.block === "if") {
+          if (value) stack.push(nodesInScopes(node.children, [scope]));
+        } else if (Array.isArray(value)) {
+          stack.push(nodesInScopes(node.children, value));
+        }
+        break;
+      }
+    }
+  }
+
+  return output.join("");
+}
+
+function* nodesInScopes(nodes: readonly TemplateNode[], scopes: Iterable<unknown>) {
+  for (const scope of scopes) {
+    for (const node of nodes) {
+      yield { node, scope };
+    }
+  }
+}
+
+function resolvePath(scope: unknown, path: string): unknown {
+  let value = scope;
+  for (const segment of path.split(".")) {
+    if (value == null) return undefined;
+    value = (value as Record<string, unknown>)[segment];
+  }
+  return value;
+}
+
+function escapeHtml(value: string): string {
+  return value
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
 }
