+  const tokens: TemplateToken[] = [];
+  const tags = /\{\{(\{?)([^{}]*)\}\}/g;
+  let textStart = 0;
+
+  for (let match = tags.exec(template); match; match = tags.exec(template)) {
+    const [, extraBrace, body] = match;
+    if (extraBrace) {
+      // An incomplete raw tag is literal, not an overlapping escaped tag.
+      if (template[tags.lastIndex] !== "}") continue;
+      tags.lastIndex++;
+    }
