+    const token = readTag(body, !extraBrace, match.index);
+    if (!token) continue;
+    if (textStart < match.index) {
+      tokens.push({ kind: "text", value: template.slice(textStart, match.index), position: textStart });
+    }
+    tokens.push(token);
+    textStart = tags.lastIndex;
+  }
+
+  if (textStart < template.length) {
+    tokens.push({ kind: "text", value: template.slice(textStart), position: textStart });
+  }
+  return tokens;
