+function readTag(body: string, escaped: boolean, position: number): TemplateToken | undefined {
+  const path = body.trim();
+  if (!path) return;
+  if (!escaped || (path[0] !== "#" && path[0] !== "/")) {
+    return { kind: "variable", path, escaped, position };
+  }
