+  const [, marker, block, argument] = /^([#/])(\S+)(?:\s+(.+))?$/s.exec(path) ?? [];
+  if (block !== "if" && block !== "each") return;
+  if (marker === "#" && argument) return { kind: "open", block, path: argument, position };
