+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | Extract<TemplateToken, { kind: "text" | "variable" }>
+  | (Extract<TemplateToken, { kind: "open" }> & { children: TemplateNode[] });
+
+/** Builds nested bodies, throwing TemplateError at the offending close or unclosed open. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: Extract<TemplateNode, { kind: "open" }>[] = [];
+  let body = root;
+
+  for (const token of tokens) {
+    if (token.kind === "open") {
+      const node = { ...token, children: [] };
+      body.push(node);
+      stack.push(node);
+      body = node.children;
+    } else if (token.kind === "close") {
+      const open = stack.at(-1);
+      if (!open) {
+        throw new TemplateError(`Unexpected closing tag: ${token.block}`, token.position);
+      }
+      if (open.block !== token.block) {
+        throw new TemplateError(`Mismatched closing tag: ${token.block}`, token.position);
+      }
+      stack.pop();
+      body = stack.at(-1)?.children ?? root;
+    } else {
+      body.push(token);
+    }
+  }
+
+  const unclosed = stack.at(-1);
+  if (unclosed) {
+    throw new TemplateError(`Unclosed block: ${unclosed.block}`, unclosed.position);
+  }
+  return root;
+}
