+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;")
+          .replaceAll('"', "&quot;")
+          .replaceAll("'", "&#39;")
+        : text;
+    } else if (node.block === "if") {
+      if (value) output += renderNodes(node.children, context);
