+import { describe, expect, spyOn, test } from "bun:test";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+
+const thinking = { kind: "item", item: { kind: "thinking", index: 0, text: "Thinking" } } as const;
+const text = { kind: "item", item: { kind: "text", index: 2, text: "Hello" } } as const;
+const stop = { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } } as const;
+const model = "claude-sonnet-4-6";
+
+/** Makes a wall clock bound expire on the first check, without spending time on a row that never comes. */
+function expiringClock() {
+  let now = Date.now();
+  return spyOn(Date, "now").mockImplementation(() => { now += 120_000; return now; });
+}
+
+describe("a hosted step's Anthropic stream", () => {
+  test("a signed row written at stop lets withheld chunks replay in Anthropic order", async () => {
+    using _clock = expiringClock();
+    const rows: SignedBlock[] = [{ type: "thinking", thinking: "Prior step", signature: "prior-signature" }];
+    const signed = { type: "thinking", thinking: "Thinking it through", signature: "signature" } as const;
+    const redacted = { type: "redacted_thinking", data: "redacted-data" } as const;
+    const progress: number[] = [];
+    const answers: HostedAnswer[] = [];
+    let received = 0;
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      received += 1;
+      yield text;
+      received += 1;
+      yield { kind: "item", item: { kind: "text", index: 2, text: " world" } };
+      rows.push(signed, redacted);
+      received += 1;
+      yield stop;
+    }
+    const actual = await Array.fromAsync(hostedStreamEvents(events(), { read: () => rows }, 1, model, async () => new Error("no stop"), (answer) => { answers.push(answer); }, () => { progress.push(received); }));
+
+    expect(actual.map((event) => event.type)).toEqual([
+      "message_start", "content_block_start", "content_block_delta", "content_block_delta", "content_block_delta", "content_block_stop",
+      "content_block_start", "content_block_stop", "content_block_start", "content_block_delta", "content_block_delta", "content_block_stop",
+      "message_delta", "message_stop",
+    ]);
+    expect(actual.slice(2, 8)).toEqual([
+      { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "Thinking" } },
+      { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: " it through" } },
+      { type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "signature" } },
+      { type: "content_block_stop", index: 0 },
+      { type: "content_block_start", index: 1, content_block: redacted },
+      { type: "content_block_stop", index: 1 },
+    ]);
+    expect(progress).toEqual([1, 2, 3]);
+    expect(answers).toEqual([{ message: { role: "assistant", content: [signed, redacted, { type: "text", text: "Hello world" }] }, stopReason: "end_turn" }]);
+  });
+
+  test("polling for a row after stop does not report extra stream progress", async () => {
+    let stopped = false;
+    let readsAfterStop = 0;
+    let progress = 0;
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      stopped = true;
+      yield stop;
+    }
+    const rows = {
+      read(): readonly SignedBlock[] {
+        return stopped && ++readsAfterStop > 1 ? [{ type: "thinking", thinking: "Thinking", signature: "late-signature" }] : [];
+      },
+    };
+    const actual = await Array.fromAsync(hostedStreamEvents(events(), rows, 0, model, async () => new Error("no stop"), () => {}, () => { progress += 1; }));
+    expect(actual).toContainEqual({ type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "late-signature" } });
+    expect(actual.at(-1)).toEqual({ type: "message_stop" });
+    expect(progress).toBe(1);
+  });
+
+  test("a row that never arrives fails transient after the stop chunk", async () => {
+    using _clock = expiringClock();
+    const progress: number[] = [];
+    let received = 0;
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      received += 1;
+      yield text;
+      received += 1;
+      yield stop;
+    }
+    const result = Array.fromAsync(hostedStreamEvents(events(), { read: () => [] }, 0, model, async () => new Error("no stop"), () => {}, () => { progress.push(received); }));
+    await expect(result).rejects.toBeInstanceOf(LlmStreamError);
+    await expect(result).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    expect(received).toBe(2);
+    expect(progress).toEqual([1, 2]);
+  });
+
+  test("a step that ends while a row is pending and has no stop chunk reports the service failure", async () => {
+    using _clock = expiringClock();
+    const serviceError = new Error("404 status code (no body)");
+    async function* events(): AsyncGenerator<StepEvent> {
+      yield thinking;
+      yield text;
+      yield { kind: "done" };
+    }
+    const result = Array.fromAsync(hostedStreamEvents(events(), { read: () => [] }, 0, model, async () => serviceError, () => {}, () => {}));
+    await expect(result).rejects.toBe(serviceError);
+  });
+});

