+import type { InternalOptions, NestedTestConfig } from '../types';
+
+type NestedCastConfig = {
+  parent: unknown[];
+  index: number;
+  value: unknown;
+};
+
+export default function getNestedOptions<TContext>(
+  config: (NestedCastConfig | Omit<NestedTestConfig, 'options'>) & {
+    options: InternalOptions<TContext>;
+  },
+) {
+  const { options, parent, index } = config;
+  const isValidation = 'originalParent' in config;
+  const key = isValidation ? config.key ?? index : index;
+  if (key == null) {
+    throw TypeError('Must include `key` or `index` for nested validations');
+  }
+
+  const isIndex = typeof key === 'number';
+  const value = isValidation ? parent[key] : config.value;
+  const parentPath = isValidation ? config.parentPath : options.path;
+
+  return {
+    ...options,
+    parent,
+    value,
+    originalValue: isValidation ? config.originalParent[key] : value,
+    // Object fields still inherit the index of their containing item.
+    ...(isIndex ? { key: undefined, index: key } : { key }),
+    path:
+      isIndex || key.includes('.')
+        ? `${parentPath || ''}[${isIndex ? key : `"${key}"`}]`
+        : (parentPath ? `${parentPath}.` : '') + key,
+  };
+}
