+import { TemplateError, type TemplateToken } from "./types.js";
+
+type BlockNode = Omit<Extract<TemplateToken, { kind: "open" }>, "kind"> & {
+  kind: "block";
+  children: TemplateNode[];
+};
+
+export type TemplateNode = Extract<TemplateToken, { kind: "text" | "variable" }> | BlockNode;
+
+/** Build a nested tree from template tokens or throw TemplateError for invalid structure. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const nodes: TemplateNode[] = [];
+  const stack: BlockNode[] = [];
+
+  for (const token of tokens) {
+    const parent = stack.at(-1);
+    if (token.kind === "close") {
+      if (!parent) {
+        throw new TemplateError(`Unexpected closing tag for ${token.block}`, token.position);
+      }
+      if (parent.block !== token.block) {
+        throw new TemplateError(`Mismatched closing tag for ${token.block}; expected ${parent.block}`, token.position);
+      }
+      stack.pop();
+    } else if (token.kind === "open") {
+      const block: BlockNode = { ...token, kind: "block", children: [] };
+      (parent?.children ?? nodes).push(block);
+      stack.push(block);
+    } else {
+      (parent?.children ?? nodes).push(token);
+    }
+  }
+
+  const unclosed = stack.at(-1);
+  if (unclosed) {
+    throw new TemplateError(`Unclosed ${unclosed.block} block`, unclosed.position);
+  }
+  return nodes;
+}
