+type RenderFrame =
+  | { nodes: Iterator<TemplateNode>; context: unknown }
+  | { items: Iterator<unknown>; body: TemplateNode[] };
+
+/** Render a template with the supplied context. Throws TemplateError for invalid block structure. */
+export function render(template: string, context: TemplateContext = {}): string {
+  const stack: RenderFrame[] = [{ nodes: parse(tokenize(template)).values(), context }];
+  const output: string[] = [];
+
+  for (let frame = stack.at(-1); frame; frame = stack.at(-1)) {
+    if ("items" in frame) {
+      const item = frame.items.next();
+      if (item.done) stack.pop();
+      else stack.push({ nodes: frame.body.values(), context: item.value });
+      continue;
+    }
+
+    const next = frame.nodes.next();
+    if (next.done) {
+      stack.pop();
+      continue;
+    }
+
+    const node = next.value;
+    if (node.kind === "text") {
+      output.push(node.value);
+      continue;
+    }
+
+    const value = resolvePath(frame.context, node.path);
+    if (node.kind === "variable") {
+      const text = value == null ? "" : String(value);
+      output.push(node.escaped ? escapeHtml(text) : text);
+    } else if (node.block === "if") {
+      if (value) stack.push({ nodes: node.children.values(), context: frame.context });
+    } else if (Array.isArray(value)) {
+      stack.push({ items: Array.prototype.values.call(value), body: node.children });
+    }
+  }
+
+  return output.join("");
+}
+
+function resolvePath(context: unknown, path: string): unknown {
+  let value = context;
+  for (const key of path.split(".")) {
+    if (value == null) return undefined;
+    value = (value as Record<string, unknown>)[key];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
