@@ -0,0 +1,47 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+type BlockNode = Extract<TemplateToken, { kind: "open" }> & {
+  children: TemplateNode[];
+};
+
+export type TemplateNode =
+  | Extract<TemplateToken, { kind: "text" | "variable" }>
+  | BlockNode;
+
+/** Builds the template tree or throws TemplateError at an unmatched block boundary. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const roots: TemplateNode[] = [];
+  const stack: BlockNode[] = [];
+
+  for (const token of tokens) {
+    const parent = stack.at(-1);
+    if (token.kind === "close") {
+      if (!parent) {
+        throw new TemplateError(`Unexpected closing tag: /${token.block}`, token.position);
+      }
+      if (parent.block !== token.block) {
+        throw new TemplateError(
+          `Mismatched closing tag: expected /${parent.block}, found /${token.block}`,
+          token.position,
+        );
+      }
+      stack.pop();
+      continue;
+    }
+
+    const children = parent ? parent.children : roots;
+    if (token.kind === "open") {
+      const block: BlockNode = { ...token, children: [] };
+      children.push(block);
+      stack.push(block);
+    } else {
+      children.push(token);
+    }
+  }
+
+  const unclosed = stack.at(-1);
+  if (unclosed) {
+    throw new TemplateError(`Unclosed block: #${unclosed.block}`, unclosed.position);
+  }
+  return roots;
+}
