+        stack.push({ nodes: frame.nodes, context: frame.items[frame.nextItem++], nextNode: 0 });
+      }
+      continue;
+    }
+
+    const node = frame.nodes[frame.nextNode++];
+    if (!node) {
+      stack.pop();
+      continue;
+    }
+    if (node.kind === "text") {
+      output.push(node.value);
+      continue;
+    }
+
+    const value = resolvePath(frame.context, node.path);
+    if (node.kind === "variable") {
+      const text = String(value ?? "");
+      output.push(node.escaped ? escapeHtml(text) : text);
+    } else if (node.block === "if") {
+      if (value) {
+        stack.push({ nodes: node.children, context: frame.context, nextNode: 0 });
+      }
+    } else if (Array.isArray(value)) {
+      stack.push({ nodes: node.children, items: value, nextItem: 0 });
+    }
+  }
