+  return output.join("");
+}
+
+function resolvePath(context: unknown, path: string): unknown {
+  let value = context;
+  for (const segment of path.split(".")) {
+    if (value == null) return undefined;
+    const scope: Record<string, unknown> = Object(value);
+    if (!Object.hasOwn(scope, segment)) return undefined;
+    value = scope[segment];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text.replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
